/**
 * CMS 路由层
 * 暴露前台公开 API 与后台管理接口
 * 响应格式严格对齐 cizhenyu_payload: { status: 200, msg: 'ok', data: ... }
 */
import { Hono } from 'hono'
import type { Env } from '../types'
import type { CmsCategoryType } from '../../shared/cmsTypes'
import {
  getCmsCategories,
  createCmsCategory,
  updateCmsCategory,
  deleteCmsCategory,
  getCmsArticles,
  getCmsArticleById,
  createCmsArticle,
  updateCmsArticle,
  deleteCmsArticle,
  getCmsProducts,
  getCmsProductById,
  createCmsProduct,
  updateCmsProduct,
  deleteCmsProduct
} from '../db/cms'

export const cmsRouter = new Hono<{ Bindings: Env }>()

// ==================== 分类接口 (content_category / product_category) ====================

// 列表查询（前后台通用，支持 ?locale=zh-CN 扁平化多语言名称）
cmsRouter.get('/cms/categories', async (c) => {
  try {
    const type = c.req.query('type') as CmsCategoryType | undefined
    const locale = c.req.query('locale') || c.req.query('lang')
    const list = await getCmsCategories(c.env.DB, type, locale)
    return c.json({ status: 200, msg: 'ok', data: list }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: '获取分类失败: ' + err.message, data: null }, 500)
  }
})

// 创建分类（后台接口）
cmsRouter.post('/admin/cms/categories', async (c) => {
  try {
    const body = await c.req.json()
    if (!body.slug || (!body.name_json && !body.name)) {
      return c.json({ status: 400, msg: '分类标识 (slug) 与分类名称为必填项', data: null }, 400)
    }
    const created = await createCmsCategory(c.env.DB, body)
    return c.json({ status: 200, msg: 'ok', data: created }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: '创建分类失败: ' + err.message, data: null }, 500)
  }
})

// 更新分类（后台接口）
cmsRouter.put('/admin/cms/categories/:id', async (c) => {
  try {
    const id = c.req.param('id')
    const body = await c.req.json()
    await updateCmsCategory(c.env.DB, id, body)
    return c.json({ status: 200, msg: 'ok', data: null }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: '更新分类失败: ' + err.message, data: null }, 500)
  }
})

// 删除分类（后台接口）
cmsRouter.delete('/admin/cms/categories/:id', async (c) => {
  try {
    const id = c.req.param('id')
    await deleteCmsCategory(c.env.DB, id)
    return c.json({ status: 200, msg: 'ok', data: null }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: '删除分类失败: ' + err.message, data: null }, 500)
  }
})

// ==================== 文章接口 (article) ====================

// 列表查询（前后台通用，返回 { status: 200, msg: 'ok', data: { list, pages } }）
cmsRouter.get('/cms/articles', async (c) => {
  try {
    const categoryId = c.req.query('categoryId') || c.req.query('taxonomyId')
    const status = c.req.query('status')
    const locale = c.req.query('locale') || c.req.query('lang')
    const search = c.req.query('search')
    const page = Number(c.req.query('page')) || 1
    const pageSize = Number(c.req.query('pageSize') || c.req.query('limit')) || 20

    const result = await getCmsArticles(c.env.DB, { categoryId, status, locale, search, page, pageSize })
    return c.json({ status: 200, msg: 'ok', data: result }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: '获取文章列表失败: ' + err.message, data: null }, 500)
  }
})

// 单篇详情
cmsRouter.get('/cms/articles/:id', async (c) => {
  try {
    const id = c.req.param('id')
    const locale = c.req.query('locale') || c.req.query('lang')
    const article = await getCmsArticleById(c.env.DB, id, locale)
    if (!article) {
      return c.json({ status: 404, msg: '文章不存在', data: null }, 404)
    }
    return c.json({ status: 200, msg: 'ok', data: article }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: '获取文章详情失败: ' + err.message, data: null }, 500)
  }
})

// 创建文章（后台接口）
cmsRouter.post('/admin/cms/articles', async (c) => {
  try {
    const body = await c.req.json()
    if (!body.slug) {
      return c.json({ status: 400, msg: '文章标识 (slug) 为必填项', data: null }, 400)
    }
    const created = await createCmsArticle(c.env.DB, body)
    return c.json({ status: 200, msg: 'ok', data: created }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: '创建文章失败: ' + err.message, data: null }, 500)
  }
})

// 更新文章（后台接口）
cmsRouter.put('/admin/cms/articles/:id', async (c) => {
  try {
    const id = c.req.param('id')
    const body = await c.req.json()
    await updateCmsArticle(c.env.DB, id, body)
    return c.json({ status: 200, msg: 'ok', data: null }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: '更新文章失败: ' + err.message, data: null }, 500)
  }
})

// 删除文章（后台接口）
cmsRouter.delete('/admin/cms/articles/:id', async (c) => {
  try {
    const id = c.req.param('id')
    await deleteCmsArticle(c.env.DB, id)
    return c.json({ status: 200, msg: 'ok', data: null }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: '删除文章失败: ' + err.message, data: null }, 500)
  }
})

