import { Hono } from 'hono'
import type { Env } from '../types'
import {
  getOrCreateConversation,
  getConversations,
  deleteConversation,
  updateConversationContext,
  getVisitorJourneyLogs
} from '../db/conversations'
import { getMessagesByConversation, markConversationAsRead } from '../db/messages'
import { ensureDefaultAdmin, getAgentById } from '../db/auth'
import { getSystemSetting } from '../db/settings'

export const chatRouter = new Hono<{ Bindings: Env }>()

chatRouter.post('/visitor/init', async (c) => {
  try {
    await ensureDefaultAdmin(c.env.DB)
    const body = await c.req.json()
    const { visitor_id, visitor_name, visitor_lang, page_context, product_snapshot, device_info } = body
    if (!visitor_id) {
      return c.json({ success: false, message: '缺少访客唯一标识' }, 400)
    }

    const ip = c.req.header('cf-connecting-ip') || c.req.header('x-real-ip') || ''
    const cf = (c.req.raw as any)?.cf
    const country = cf?.country || ''
    const city = cf?.city || ''
    const timezone = cf?.timezone || ''
    const isp = cf?.asOrganization || ''

    const { conversation } = await getOrCreateConversation(
      c.env.DB,
      visitor_id,
      visitor_name,
      visitor_lang,
      { ip, country, city, isp, timezone },
      { page_context, product_snapshot, device_info }
    )
    const messages = await getMessagesByConversation(c.env.DB, conversation.id, 40)

    return c.json({
      success: true,
      data: {
        conversation,
        messages
      }
    })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

// 访客端上报页面上下文变化与足迹 (SPA 路由切换与浏览行为)
chatRouter.post('/visitor/context', async (c) => {
  try {
    const { conversation_id, visitor_id, page_context, product_snapshot, device_info } = await c.req.json()
    if (!conversation_id || !visitor_id || !page_context) {
      return c.json({ success: false, message: '参数不完整' }, 400)
    }
    const ok = await updateConversationContext(
      c.env.DB,
      conversation_id,
      visitor_id,
      page_context,
      product_snapshot,
      device_info
    )
    return c.json({ success: ok })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

// 客服端获取访客浏览旅程轨迹
chatRouter.get('/conversations/:id/journey', async (c) => {
  try {
    const convId = c.req.param('id')
    const list = await getVisitorJourneyLogs(c.env.DB, convId)
    return c.json({ success: true, data: list })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

chatRouter.get('/conversations', async (c) => {
  try {
    const agentId = c.req.header('x-agent-id')
    const platform = c.req.query('platform')
    let isAdmin = false
    if (agentId) {
      const ag = await getAgentById(c.env.DB, agentId)
      isAdmin = ag?.role === 'admin'
    }
    const list = await getConversations(c.env.DB, agentId, isAdmin, platform)
    return c.json({ success: true, data: list })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

chatRouter.get('/conversations/:id/messages', async (c) => {
  try {
    const convId = c.req.param('id')
    const limit = Number(c.req.query('limit')) || 40
    const before = Number(c.req.query('before')) || undefined
    const messages = await getMessagesByConversation(c.env.DB, convId, limit, before)
    return c.json({ success: true, data: messages })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

chatRouter.post('/conversations/:id/read', async (c) => {
  const convId = c.req.param('id')
  const { by } = await c.req.json()
  if (by) {
    await markConversationAsRead(c.env.DB, convId, by)
  }
  return c.json({ success: true })
})

/**
 * 彻底删除某个客户的会话以及该会话下的所有聊天记录 (仅超级管理员)
 */
chatRouter.delete('/conversations/:id', async (c) => {
  try {
    const convId = c.req.param('id')
    const agentId = c.req.header('x-agent-id') || c.req.query('agent_id')
    if (agentId) {
      const { getAgentById } = await import('../db/auth')
      const agent = await getAgentById(c.env.DB, agentId)
      if (agent && agent.role !== 'admin') {
        return c.json({ success: false, message: '权限不足：仅超级管理员可以彻底删除聊天记录' }, 403)
      }
    }
    await deleteConversation(c.env.DB, convId, c.env.MEDIA_BUCKET)
    return c.json({ success: true })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

/**
 * 设置/修改客户备注标记 (tag)
 */
chatRouter.post('/conversations/:id/tag', async (c) => {
  try {
    const convId = c.req.param('id')
    const { tag } = await c.req.json()
    const { updateConversationTag } = await import('../db/conversations')
    await updateConversationTag(c.env.DB, convId, tag ? tag.trim() : null)
    return c.json({ success: true, tag })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

/**
 * 一键批量清理垃圾会话（支持未发言访客、分组、标记维度）
 */
chatRouter.post('/admin/conversations/batch-cleanup', async (c) => {
  try {
    const agentId = c.req.header('x-agent-id') || c.req.query('agent_id')
    if (agentId) {
      const { getAgentById } = await import('../db/auth')
      const agent = await getAgentById(c.env.DB, agentId)
      if (agent && agent.role !== 'admin') {
        return c.json({ success: false, message: '权限不足：仅超级管理员可以执行批量清理' }, 403)
      }
    }
    const body = await c.req.json()
    const { clean_silent, group_ids, tag_mode } = body
    const { batchCleanupConversations } = await import('../db/conversations')
    const count = await batchCleanupConversations(c.env.DB, c.env.MEDIA_BUCKET, {
      cleanSilent: clean_silent,
      groupIds: group_ids,
      tagMode: tag_mode
    })
    return c.json({ success: true, deleted_count: count })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

/**
 * 访客端组件公开配置与域名授权白名单查询接口 (24 小时边缘节点强缓存)
 */
chatRouter.get('/widget/config', async (c) => {
  try {
    const brand_color = await getSystemSetting(c.env.DB, 'widget_brand_color') || '#07c160'
    const position = await getSystemSetting(c.env.DB, 'widget_position') || 'bottom-right'
    const custom_icon = await getSystemSetting(c.env.DB, 'widget_custom_icon') || ''
    const button_title = await getSystemSetting(c.env.DB, 'widget_button_title') || '在线客服'
    const allowed_domains = await getSystemSetting(c.env.DB, 'allowed_domains') || ''
    const widget_items_json = await getSystemSetting(c.env.DB, 'widget_items_json') || ''
    const welcome_message =
      await getSystemSetting(c.env.DB, 'welcome_message_zh') ||
      await getSystemSetting(c.env.DB, 'welcome_message') ||
      '您好！欢迎使用在线客服系统，请问有什么可以帮您？'

    // 24 小时边缘强缓存，大幅压降高并发 UV 下的 Workers 请求
    c.header('Cache-Control', 'public, max-age=86400, s-maxage=86400')

    return c.json({
      success: true,
      data: {
        brand_color,
        position,
        custom_icon,
        button_title,
        allowed_domains,
        widget_items_json,
        welcome_message
      }
    })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

/**
 * 访客提交离线留言并触发多渠道即时通知
 */
chatRouter.post('/visitor/ticket', async (c) => {
  try {
    const { visitor_id, visitor_name, contact, content, conversation_id, extra_fields } = await c.req.json()
    if (!content || !contact) {
      return c.json({ success: false, message: '请完整填写联系方式与留言内容' }, 400)
    }

    const name = visitor_name || '访客'
    const now = Date.now()

    let extraText = ''
    if (extra_fields && typeof extra_fields === 'object') {
      const lines: string[] = []
      for (const [k, v] of Object.entries(extra_fields)) {
        if (k !== 'name' && k !== 'contact' && k !== 'content' && v) {
          lines.push(`${k}: ${Array.isArray(v) ? v.join(', ') : v}`)
        }
      }
      if (lines.length > 0) {
        extraText = `\n【扩展字段】\n` + lines.join('\n')
      }
    }
    const ticketContent = `【留言与需求工单】\n称呼：${name}\n联系方式：${contact}\n留言内容：${content}${extraText}`

    // 1. 如果有关联会话，将留言写入会话消息流
    if (conversation_id) {
      const msgId = 'msg_' + crypto.randomUUID().slice(0, 10)
      await c.env.DB.prepare(
        `INSERT INTO messages (
          id, conversation_id, sender_type, sender_id, sender_name,
          message_type, content, status, created_at
        ) VALUES (?, ?, 'visitor', ?, ?, 'text', ?, 'sent', ?)`
      ).bind(
        msgId,
        conversation_id,
        visitor_id || 'visitor',
        name,
        ticketContent,
        now
      ).run()

      await c.env.DB.prepare(
        'UPDATE conversations SET last_message_text = ?, last_message_time = ?, unread_agent_count = unread_agent_count + 1 WHERE id = ?'
      ).bind(ticketContent, now, conversation_id).run()

      // 通过 DurableObject 实时广播这条留言消息，免去前端二次发送导致重复两条
      try {
        const id = c.env.COORDINATOR.idFromName('global_chat_coordinator')
        const stub = c.env.COORDINATOR.get(id)
        await stub.fetch(new Request('http://coordinator/broadcast-message', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            id: msgId,
            conversation_id,
            sender_type: 'visitor',
            sender_id: visitor_id || 'visitor',
            sender_name: name,
            message_type: 'text',
            content: ticketContent,
            status: 'sent',
            created_at: now
          })
        }))
      } catch (e) {}
    }

    // 2. 异步触发多渠道通知分发（Resend / UsePlunk / Telegram / 企业微信）
    const { dispatchLeaveMessageNotification } = await import('../services/notifier')
    const notifyRes = await dispatchLeaveMessageNotification(c.env, {
      visitor_name: name,
      contact,
      content,
      conversation_id,
      visitor_id
    })

    // 3. 异步触发基于企业知识库的 AI 即时预答复 (消除留言后只能干等的痛点)
    if (conversation_id) {
      c.executionCtx.waitUntil((async () => {
        try {
          const { askKnowledge } = await import('../services/kbService')
          const { answer } = await askKnowledge(c.env, content)
          if (answer) {
            const aiReplyText = `【AI 智能预答复】\n我们已收到您的留言并已提醒人工客服稍后跟进！根据企业知识库，初步为您查询到以下参考信息：\n\n${answer}`
            const aiMsgId = 'msg_' + crypto.randomUUID().slice(0, 10)
            const aiNow = Date.now()
            await c.env.DB.prepare(
              `INSERT INTO messages (
                id, conversation_id, sender_type, sender_id, sender_name,
                message_type, content, status, created_at
              ) VALUES (?, ?, 'agent', 'ai_bot', 'AI 智能客服', 'text', ?, 'sent', ?)`
            ).bind(aiMsgId, conversation_id, aiReplyText, aiNow).run()

            await c.env.DB.prepare(
              'UPDATE conversations SET last_message_text = ?, last_message_time = ? WHERE id = ?'
            ).bind(aiReplyText, aiNow, conversation_id).run()

            const stub = c.env.COORDINATOR.get(c.env.COORDINATOR.idFromName('global_chat_coordinator'))
            await stub.fetch(new Request('http://coordinator/broadcast-message', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                id: aiMsgId,
                conversation_id,
                sender_type: 'agent',
                sender_id: 'ai_bot',
                sender_name: 'AI 智能客服',
                message_type: 'text',
                content: aiReplyText,
                status: 'sent',
                created_at: aiNow
              })
            }))
          }
        } catch (e) {
          console.warn('Failed to generate ticket pre-reply with KB', e)
        }
      })())
    }

    return c.json({
      success: true,
      message: '您的留言已成功提交，客服将尽快与您联系！',
      data: notifyRes
    })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})
