export async function getDashboardStats(db: D1Database) {
  const totalConvs = await db.prepare('SELECT COUNT(*) as c FROM conversations').first<{ c: number }>()
  const totalMsgs = await db.prepare('SELECT COUNT(*) as c FROM messages').first<{ c: number }>()
  const onlineAgents = await db.prepare("SELECT COUNT(*) as c FROM agents WHERE status != 'offline'").first<{ c: number }>()
  
  const oneDayAgo = Date.now() - 24 * 60 * 60 * 1000
  const recentConvs = await db.prepare('SELECT COUNT(*) as c FROM conversations WHERE created_at > ?').bind(oneDayAgo).first<{ c: number }>()

  return {
    totalConversations: totalConvs?.c || 0,
    totalMessages: totalMsgs?.c || 0,
    onlineAgents: onlineAgents?.c || 0,
    todayConversations: recentConvs?.c || 0
  }
}
