import type { CustomForm, FormSubmission } from '../../shared/types'

/**
 * 确保通用表单所需的两张数据表存在
 */
export async function ensureFormTables(db: D1Database): Promise<void> {
  await db.prepare(`
    CREATE TABLE IF NOT EXISTS custom_forms (
      id TEXT PRIMARY KEY,
      key TEXT UNIQUE NOT NULL,
      title TEXT NOT NULL,
      description TEXT,
      allowed_domains TEXT,
      fields_json TEXT NOT NULL,
      style_config_json TEXT,
      status TEXT DEFAULT 'active',
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL
    )
  `).run()

  await db.prepare(`
    CREATE TABLE IF NOT EXISTS form_submissions (
      id TEXT PRIMARY KEY,
      form_key TEXT NOT NULL,
      form_id TEXT,
      visitor_id TEXT,
      data_json TEXT NOT NULL,
      ip TEXT,
      country TEXT,
      city TEXT,
      source_url TEXT,
      created_at INTEGER NOT NULL
    )
  `).run()

  // 索引优化
  try {
    await db.prepare('CREATE INDEX IF NOT EXISTS idx_custom_forms_key ON custom_forms(key)').run()
    await db.prepare('CREATE INDEX IF NOT EXISTS idx_form_subs_key ON form_submissions(form_key)').run()
  } catch (e) {}
}

export async function getAllCustomForms(db: D1Database): Promise<CustomForm[]> {
  await ensureFormTables(db)
  const rows = await db.prepare(
    'SELECT * FROM custom_forms ORDER BY created_at DESC'
  ).all<any>()

  if (!rows.results) return []

  const forms: CustomForm[] = []
  for (const r of rows.results) {
    // 统计该表单的提交量
    const countRow = await db.prepare(
      'SELECT COUNT(id) as count FROM form_submissions WHERE form_key = ?'
    ).bind(r.key).first<{ count: number }>()

    let fields = []
    let style = {
      primary_color: '#07c160',
      bg_color: 'white',
      border_radius: 'medium',
      button_text: '立即提交',
      success_message: '感谢您的提交，我们已收到您的答卷！'
    }

    try { fields = JSON.parse(r.fields_json) } catch (e) {}
    try { if (r.style_config_json) style = JSON.parse(r.style_config_json) } catch (e) {}

    forms.push({
      id: r.id,
      key: r.key,
      title: r.title,
      description: r.description || '',
      allowed_domains: r.allowed_domains || '',
      fields,
      style: style as any,
      status: r.status || 'active',
      submissions_count: countRow?.count || 0,
      created_at: r.created_at,
      updated_at: r.updated_at
    })
  }

  return forms
}

export async function getCustomFormByKey(db: D1Database, key: string): Promise<CustomForm | null> {
  await ensureFormTables(db)
  const r = await db.prepare('SELECT * FROM custom_forms WHERE key = ?').bind(key).first<any>()
  if (!r) return null

  let fields = []
  let style = {
    primary_color: '#07c160',
    bg_color: 'white',
    border_radius: 'medium',
    button_text: '立即提交',
    success_message: '感谢您的提交，我们已收到您的答卷！'
  }

  try { fields = JSON.parse(r.fields_json) } catch (e) {}
  try { if (r.style_config_json) style = JSON.parse(r.style_config_json) } catch (e) {}

  return {
    id: r.id,
    key: r.key,
    title: r.title,
    description: r.description || '',
    allowed_domains: r.allowed_domains || '',
    fields,
    style: style as any,
    status: r.status || 'active',
    created_at: r.created_at,
    updated_at: r.updated_at
  }
}

export async function createCustomForm(
  db: D1Database,
  data: {
    key: string
    title: string
    description?: string
    allowed_domains?: string
    fields: any[]
    style: any
  }
): Promise<CustomForm> {
  await ensureFormTables(db)
  const id = `form_${Date.now().toString(36)}_${crypto.randomUUID().slice(0, 4)}`
  const now = Date.now()

  await db.prepare(`
    INSERT INTO custom_forms (
      id, key, title, description, allowed_domains,
      fields_json, style_config_json, status, created_at, updated_at
    ) VALUES (?, ?, ?, ?, ?, ?, ?, 'active', ?, ?)
  `).bind(
    id,
    data.key,
    data.title,
    data.description || '',
    data.allowed_domains || '',
    JSON.stringify(data.fields),
    JSON.stringify(data.style),
    now,
    now
  ).run()

  return (await getCustomFormByKey(db, data.key))!
}

export async function updateCustomForm(
  db: D1Database,
  id: string,
  data: {
    title: string
    description?: string
    allowed_domains?: string
    fields: any[]
    style: any
  }
): Promise<void> {
  await ensureFormTables(db)
  const now = Date.now()

  await db.prepare(`
    UPDATE custom_forms SET
      title = ?,
      description = ?,
      allowed_domains = ?,
      fields_json = ?,
      style_config_json = ?,
      updated_at = ?
    WHERE id = ?
  `).bind(
    data.title,
    data.description || '',
    data.allowed_domains || '',
    JSON.stringify(data.fields),
    JSON.stringify(data.style),
    now,
    id
  ).run()
}

export async function deleteCustomForm(db: D1Database, id: string): Promise<void> {
  await ensureFormTables(db)
  const form = await db.prepare('SELECT key FROM custom_forms WHERE id = ?').bind(id).first<{ key: string }>()
  if (form) {
    // 联动删除提交数据
    await db.prepare('DELETE FROM form_submissions WHERE form_key = ?').bind(form.key).run()
  }
  await db.prepare('DELETE FROM custom_forms WHERE id = ?').bind(id).run()
}

export async function getFormSubmissions(db: D1Database, formKey: string): Promise<FormSubmission[]> {
  await ensureFormTables(db)
  const rows = await db.prepare(
    'SELECT * FROM form_submissions WHERE form_key = ? ORDER BY created_at DESC LIMIT 500'
  ).bind(formKey).all<any>()

  if (!rows.results) return []

  return rows.results.map(r => {
    let data = {}
    try { data = JSON.parse(r.data_json) } catch (e) {}
    return {
      id: r.id,
      form_key: r.form_key,
      form_id: r.form_id,
      visitor_id: r.visitor_id,
      data,
      ip: r.ip,
      country: r.country,
      city: r.city,
      source_url: r.source_url,
      created_at: r.created_at
    }
  })
}

export async function insertFormSubmission(
  db: D1Database,
  data: {
    form_key: string
    visitor_id?: string
    data: Record<string, any>
    ip?: string
    country?: string
    city?: string
    source_url?: string
  }
): Promise<string> {
  await ensureFormTables(db)
  const id = `sub_${Date.now().toString(36)}_${crypto.randomUUID().slice(0, 4)}`
  const now = Date.now()

  await db.prepare(`
    INSERT INTO form_submissions (
      id, form_key, visitor_id, data_json, ip, country, city, source_url, created_at
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
  `).bind(
    id,
    data.form_key,
    data.visitor_id || 'anonymous',
    JSON.stringify(data.data),
    data.ip || '',
    data.country || '',
    data.city || '',
    data.source_url || '',
    now
  ).run()

  return id
}

export async function deleteFormSubmission(db: D1Database, id: string): Promise<void> {
  await ensureFormTables(db)
  await db.prepare('DELETE FROM form_submissions WHERE id = ?').bind(id).run()
}
