import { Hono } from 'hono'
import type { Env } from '../types'
import { getAllAgents, createAgent, updateAgent, deleteAgent } from '../db/auth'
import { getDashboardStats } from '../db/stats'
import { getSystemSettings, updateSystemSettings } from '../db/settings'

export const adminRouter = new Hono<{ Bindings: Env }>()

async function checkAdmin(c: any): Promise<boolean> {
  const agentId = c.req.header('x-agent-id') || c.req.query('agent_id')
  if (!agentId) return true
  const { getAgentById } = await import('../db/auth')
  const agent = await getAgentById(c.env.DB, agentId)
  return !agent || agent.role === 'admin'
}

adminRouter.get('/agents', async (c) => {
  try {
    const list = await getAllAgents(c.env.DB)
    return c.json({ success: true, data: list })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

adminRouter.post('/agents', async (c) => {
  try {
    if (!await checkAdmin(c)) {
      return c.json({ success: false, message: '权限不足：仅超级管理员可以管理坐席员工' }, 403)
    }
    const body = await c.req.json()
    const { username, password, display_name, role } = body
    if (!username || !password || !display_name) {
      return c.json({ success: false, message: '请完整填写员工信息' }, 400)
    }
    await createAgent(c.env.DB, { username, password, display_name, role })
    return c.json({ success: true })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 400)
  }
})

adminRouter.put('/agents/:id', async (c) => {
  try {
    if (!await checkAdmin(c)) {
      return c.json({ success: false, message: '权限不足：仅超级管理员可以修改坐席信息' }, 403)
    }
    const id = c.req.param('id')
    const body = await c.req.json()
    await updateAgent(c.env.DB, id, body)
    return c.json({ success: true })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 400)
  }
})

adminRouter.delete('/agents/:id', async (c) => {
  try {
    if (!await checkAdmin(c)) {
      return c.json({ success: false, message: '权限不足：仅超级管理员可以删除坐席员工' }, 403)
    }
    const id = c.req.param('id')
    await deleteAgent(c.env.DB, id)
    return c.json({ success: true })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 400)
  }
})

adminRouter.get('/stats', async (c) => {
  try {
    const stats = await getDashboardStats(c.env.DB)
    return c.json({ success: true, data: stats })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

adminRouter.get('/settings', async (c) => {
  try {
    const data = await getSystemSettings(c.env.DB)
    return c.json({ success: true, data })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

adminRouter.post('/settings', async (c) => {
  try {
    if (!await checkAdmin(c)) {
      return c.json({ success: false, message: '权限不足：仅超级管理员可以修改系统配置' }, 403)
    }
    const body = await c.req.json()
    await updateSystemSettings(c.env.DB, body)
    return c.json({ success: true })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

