import { Hono } from 'hono'
import type { Env } from '../types'

export const uploadRouter = new Hono<{ Bindings: Env }>()

uploadRouter.post('/upload', async (c) => {
  try {
    const formData = await c.req.parseBody()
    const file = formData['file'] as File | undefined

    if (!file) {
      return c.json({ success: false, message: '未找到上传文件' }, 400)
    }

    const ext = file.name ? file.name.split('.').pop() || 'bin' : 'bin'
    const today = new Date().toISOString().slice(0, 10).replace(/-/g, '')
    const fileKey = `${today}/${crypto.randomUUID()}.${ext}`

    const arrayBuffer = await file.arrayBuffer()

    await c.env.MEDIA_BUCKET.put(fileKey, arrayBuffer, {
      httpMetadata: {
        contentType: file.type || 'application/octet-stream'
      }
    })

    // 返回绝对 URL，避免挂件嵌入第三方域名后相对路径打到宿主站
    const origin = new URL(c.req.url).origin
    const url = `${origin}/media/${fileKey}`

    return c.json({
      success: true,
      data: {
        url,
        fileKey,
        fileName: file.name,
        fileSize: file.size,
        contentType: file.type
      }
    })
  } catch (err: any) {
    return c.json({ success: false, message: '上传失败: ' + err.message }, 500)
  }
})

uploadRouter.get('/media/*', async (c) => {
  const rawPath = c.req.path
  const fileKey = rawPath.replace(/^\/media\//, '')
  if (!fileKey) return c.text('Not found', 404)

  const object = await c.env.MEDIA_BUCKET.get(fileKey)
  if (!object) return c.text('Media not found', 404)

  const headers = new Headers()
  object.writeHttpMetadata(headers)
  headers.set('etag', object.httpEtag)
  headers.set('Cache-Control', 'public, max-age=31536000, immutable')

  return new Response(object.body, { headers })
})
