import type { PrivateChat } from '../types'
import { hashPassword } from '../utils/crypto'
import { deleteConversationMediaFromR2 } from './conversations'

/**
 * 创建一条专属私密聊天
 */
export async function createPrivateChat(
  db: D1Database,
  title: string,
  password: string,
  agentId: string,
  expiresHours?: number
): Promise<PrivateChat> {
  const id = 'sec_' + crypto.randomUUID().slice(0, 10)
  const now = Date.now()
  const pwdHash = await hashPassword(password)
  const expiresAt = expiresHours && expiresHours > 0 ? now + expiresHours * 3600 * 1000 : null

  await db.prepare(
    `INSERT INTO private_chats (
      id, title, password_hash, plain_password, agent_id, status, last_message_text, last_message_time, created_at, expires_at
    ) VALUES (?, ?, ?, ?, ?, 'active', '私密会话已创建', ?, ?, ?)`
  ).bind(
    id,
    title,
    pwdHash,
    password,
    agentId,
    now,
    now,
    expiresAt
  ).run()

  // 并在 conversations 表中建立映射，以便统一走消息系统与 WebSocket 协调器
  await db.prepare(
    `INSERT INTO conversations (
      id, visitor_id, visitor_name, assigned_agent_id, group_id, status,
      unread_agent_count, unread_visitor_count, last_message_text,
      last_message_time, created_at
    ) VALUES (?, ?, ?, ?, 'grp_vip', 'active', 0, 0, '私密会话已创建', ?, ?)`
  ).bind(
    id,
    `sec_client_${id.slice(-4)}`,
    `[私密] ${title}`,
    agentId,
    now,
    now
  ).run()

  return {
    id,
    title,
    password_hash: pwdHash,
    plain_password: password,
    agent_id: agentId,
    status: 'active',
    last_message_text: '私密会话已创建',
    last_message_time: now,
    created_at: now,
    expires_at: expiresAt
  }
}

/**
 * 校验专属私聊密码
 */
export async function verifyPrivateChatPassword(
  db: D1Database,
  id: string,
  password: string
): Promise<{ success: boolean; chat?: PrivateChat; message?: string }> {
  const chat = await db.prepare('SELECT * FROM private_chats WHERE id = ?').bind(id).first<PrivateChat>()
  if (!chat) {
    return { success: false, message: '私密聊天不存在或已被删除' }
  }

  if (chat.expires_at && chat.expires_at < Date.now()) {
    return { success: false, message: '该私密聊天已过期失效' }
  }

  const inputHash = await hashPassword(password)
  if (chat.password_hash !== inputHash) {
    return { success: false, message: '私密访问密码错误' }
  }

  return { success: true, chat }
}

/**
 * 获取所有私密聊天列表
 */
export async function getPrivateChats(db: D1Database): Promise<PrivateChat[]> {
  const res = await db.prepare(
    'SELECT id, title, plain_password, agent_id, status, last_message_text, last_message_time, created_at, expires_at FROM private_chats ORDER BY created_at DESC'
  ).all<PrivateChat>()
  return res.results || []
}

/**
 * 删除专属私密聊天
 */
export async function deletePrivateChat(db: D1Database, id: string, bucket?: R2Bucket): Promise<void> {
  await deleteConversationMediaFromR2(db, bucket, id)
  await db.prepare('DELETE FROM messages WHERE conversation_id = ?').bind(id).run()
  await db.prepare('DELETE FROM conversations WHERE id = ?').bind(id).run()
  await db.prepare('DELETE FROM private_chats WHERE id = ?').bind(id).run()
}
