import type { Env, Message, WSPacket } from './types'
import { insertMessage, markConversationAsRead, getMessagesByConversation } from './db/messages'
import { askKnowledge } from './services/kbService'
import { getSystemSetting } from './db/settings'

/**
 * 实时通讯协调器 (ChatCoordinator)
 * 基于 Cloudflare SQLite Durable Object 与 WebSocket Hibernation 实现
 * 负责跨会话与客服长连接管理、状态监听与毫秒级广播
 */
export class ChatCoordinator implements DurableObject {
  ctx: DurableObjectState
  env: Env

  constructor(ctx: DurableObjectState, env: Env) {
    this.ctx = ctx
    this.env = env
  }

  async fetch(request: Request): Promise<Response> {
    const url = new URL(request.url)
    const upgradeHeader = request.headers.get('Upgrade')

    // 内部 HTTP 广播端点（用于状态变更时全网实时广播）
    if (url.pathname === '/broadcast-status' && request.method === 'POST') {
      try {
        const body = await request.json()
        const sockets = this.ctx.getWebSockets()
        const payload = JSON.stringify({
          type: 'agent_status_change',
          data: body
        })
        for (const s of sockets) {
          try {
            s.send(payload)
          } catch (err) {}
        }
        return new Response(JSON.stringify({ success: true }), {
          headers: { 'Content-Type': 'application/json' }
        })
      } catch (e: any) {
        return new Response(JSON.stringify({ success: false, error: e.message }), { status: 500 })
      }
    }

    // 内部 HTTP 留言/单条消息广播端点
    if (url.pathname === '/broadcast-message' && request.method === 'POST') {
      try {
        const savedMsg = await request.json() as any
        this.broadcastToConversation(savedMsg.conversation_id, {
          type: 'message',
          data: savedMsg
        })
        this.broadcastToAgents({
          type: 'conversation_update',
          data: {
            conversation_id: savedMsg.conversation_id,
            last_message: savedMsg
          }
        })
        return new Response(JSON.stringify({ success: true }), {
          headers: { 'Content-Type': 'application/json' }
        })
      } catch (e: any) {
        return new Response(JSON.stringify({ success: false, error: e.message }), { status: 500 })
      }
    }

    if (upgradeHeader !== 'websocket') {
      return new Response('Expected WebSocket upgrade', { status: 426 })
    }

    const role = url.searchParams.get('role') || 'visitor'
    const conversationId = url.searchParams.get('cid') || ''
    const userId = url.searchParams.get('uid') || ''

    // 创建 WebSocket 客户端与服务端对
    const webSocketPair = new WebSocketPair()
    const [client, server] = Object.values(webSocketPair)

    // NOTE: 使用 WebSocket Hibernation API 打标签，长连接休眠时不消耗计费时长
    const tags: string[] = [`role:${role}`]
    if (conversationId) {
      tags.push(`cid:${conversationId}`)
    }
    if (userId) {
      tags.push(`uid:${userId}`)
    }

    this.ctx.acceptWebSocket(server, tags)

    // 给刚连上的客户端发送一个初始握手包
    server.send(JSON.stringify({
      type: 'init',
      data: {
        status: 'connected',
        role,
        conversationId,
        serverTime: Date.now()
      }
    }))

    return new Response(null, {
      status: 101,
      webSocket: client
    })
  }

  /**
   * 当收到客户端 WebSocket 消息时触发
   */
  async webSocketMessage(ws: WebSocket, rawMessage: string | ArrayBuffer): Promise<void> {
    try {
      const text = typeof rawMessage === 'string' ? rawMessage : new TextDecoder().decode(rawMessage)
      const packet = JSON.parse(text) as WSPacket

      if (packet.type === 'message') {
        const msgPayload = packet.data as Message
        if (!msgPayload || !msgPayload.conversation_id || !msgPayload.content) {
          return
        }

        // 1. 持久化到 Cloudflare D1 边缘数据库
        const savedMsg = await insertMessage(this.env.DB, msgPayload)

        // 2. 广播给该会话中的所有订阅者 (访客自身与正在查看该会话的端)
        this.broadcastToConversation(savedMsg.conversation_id, {
          type: 'message',
          data: savedMsg
        })

        // 3. 同时广播给所有客服（通知客服工作台更新会话列表和未读计数）
        this.broadcastToAgents({
          type: 'conversation_update',
          data: {
            conversation_id: savedMsg.conversation_id,
            last_message: savedMsg
          }
        })

        // 4. 根据后台设置的策略精准触发企业知识库 AI 自动问答
        if (savedMsg.sender_type === 'visitor' && savedMsg.message_type === 'text') {
          this.ctx.waitUntil((async () => {
            try {
              // 读取后台配置的接待策略 (默认 'always' 总是优先秒级响应)
              const strategy = (await getSystemSetting(this.env.DB, 'ai_reply_strategy')) || 'always'
              if (strategy === 'disabled') return

              const isExplicitAi = savedMsg.content.toLowerCase().startsWith('@ai')
              let shouldTrigger = false

              if (isExplicitAi) {
                shouldTrigger = true
              } else if (strategy === 'always') {
                shouldTrigger = true
              } else if (strategy === 'offline_only') {
                // 精准查询数据库中是否真正存在 status = 'online' 的坐席
                const onlineRes = await this.env.DB.prepare(
                  "SELECT count(1) as count FROM agents WHERE status = 'online'"
                ).first<{ count: number }>()
                const hasOnlineAgent = (onlineRes?.count || 0) > 0
                const agentSockets = this.ctx.getWebSockets('role:agent')
                // 只有当业务状态在线且存在活跃连接时才视为真正有人工值守；否则 AI 立即接管
                const hasRealAgent = hasOnlineAgent && agentSockets.length > 0
                shouldTrigger = !hasRealAgent
              }

              if (shouldTrigger) {
                const queryText = savedMsg.content.replace(/^@ai\s*/i, '').trim()
                if (!queryText) return

                // 拉取最近 4 条历史会话消息，为大模型提供多轮问答上下文
                const recentMsgs = await getMessagesByConversation(this.env.DB, savedMsg.conversation_id, 4)
                const convHistory = recentMsgs.reverse().map(m => ({
                  role: (m.sender_type === 'visitor' ? 'user' : 'assistant') as 'user' | 'assistant',
                  content: m.content
                }))

                const { answer } = await askKnowledge(this.env, queryText, convHistory)
                if (answer) {
                  const aiMsgPayload: Message = {
                    id: `msg_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`,
                    conversation_id: savedMsg.conversation_id,
                    sender_type: 'agent',
                    sender_id: 'ai_bot',
                    sender_name: 'AI 智能客服',
                    message_type: 'text',
                    content: answer,
                    status: 'sent',
                    created_at: Date.now()
                  }
                  const savedAiMsg = await insertMessage(this.env.DB, aiMsgPayload)
                  this.broadcastToConversation(savedAiMsg.conversation_id, {
                    type: 'message',
                    data: savedAiMsg
                  })
                  this.broadcastToAgents({
                    type: 'conversation_update',
                    data: {
                      conversation_id: savedAiMsg.conversation_id,
                      last_message: savedAiMsg
                    }
                  })
                }
              }
            } catch (e) {
              console.warn('Failed to auto answer with KB RAG', e)
            }
          })())
        }
      } else if (packet.type === 'read') {
        // 已读上报
        const { conversation_id, by } = packet.data || {}
        if (conversation_id && by) {
          await markConversationAsRead(this.env.DB, conversation_id, by)
          this.broadcastToConversation(conversation_id, {
            type: 'read',
            data: { conversation_id, by }
          })
        }
      } else if (
        packet.type === 'call_invite' ||
        packet.type === 'call_accept' ||
        packet.type === 'call_reject' ||
        packet.type === 'call_hangup' ||
        packet.type === 'webrtc_offer' ||
        packet.type === 'webrtc_answer' ||
        packet.type === 'webrtc_ice'
      ) {
        // WebRTC 实时音视频信令转发
        const convId = packet.data?.conversation_id
        if (convId) {
          this.broadcastToConversation(convId, packet)
        }
      } else if (packet.type === 'pong') {
        // 心跳应答，保持存活
      }
    } catch (err) {
      console.error('Error handling websocket message:', err)
    }
  }

  /**
   * 当 WebSocket 连接关闭时触发
   */
  async webSocketClose(ws: WebSocket, code: number, reason: string, wasClean: boolean): Promise<void> {
    ws.close(code, reason)
  }

  /**
   * 当 WebSocket 出现错误时触发
   */
  async webSocketError(ws: WebSocket, error: unknown): Promise<void> {
    console.error('WebSocket error:', error)
  }

  /**
   * 向指定会话的所有活跃连接广播数据包
   */
  private broadcastToConversation(conversationId: string, packet: any): void {
    const sockets = this.ctx.getWebSockets(`cid:${conversationId}`)
    const payload = JSON.stringify(packet)
    for (const ws of sockets) {
      try {
        ws.send(payload)
      } catch (e) {
        console.warn('Failed to send to client socket:', e)
      }
    }
  }

  /**
   * 向所有在线客服连接广播数据包
   */
  private broadcastToAgents(packet: any): void {
    const sockets = this.ctx.getWebSockets('role:agent')
    const payload = JSON.stringify(packet)
    for (const ws of sockets) {
      try {
        ws.send(payload)
      } catch (e) {
        console.warn('Failed to send to agent socket:', e)
      }
    }
  }
}
