/**
 * 将文本智能切分成具有语义重叠的分块 (Chunks)
 * @param text 待切分长文本
 * @param maxChars 每个分块目标字符数 (默认 600)
 * @param overlap 字符重叠率 (默认 80)
 */
export function splitTextIntoChunks(text: string, maxChars = 600, overlap = 80): string[] {
  const clean = text.trim()
  if (!clean) return []
  if (clean.length <= maxChars) return [clean]

  const chunks: string[] = []
  let start = 0

  while (start < clean.length) {
    let end = start + maxChars
    if (end >= clean.length) {
      chunks.push(clean.substring(start).trim())
      break
    }

    // 尽量在标点符号或段落换行处断句
    const slice = clean.substring(start, end)
    const breakCandidates = [
      slice.lastIndexOf('\n\n'),
      slice.lastIndexOf('\n'),
      slice.lastIndexOf('。'),
      slice.lastIndexOf('！'),
      slice.lastIndexOf('？'),
      slice.lastIndexOf('. '),
      slice.lastIndexOf('; '),
      slice.lastIndexOf('；')
    ]
    const bestBreak = Math.max(...breakCandidates)

    if (bestBreak > maxChars * 0.4) {
      end = start + bestBreak + 1
    }

    const chunkContent = clean.substring(start, end).trim()
    if (chunkContent.length > 0) {
      chunks.push(chunkContent)
    }

    start = end - overlap
    if (start >= clean.length) break
  }

  return chunks
}

/**
 * 索引并向量化知识库文档 (Ingestion Pipeline)
 * @param env 环境变量
 * @param doc 知识库文档
 */
export async function indexDocument(env: Env, doc: KbDocument): Promise<{ success: boolean; chunksCount: number; error?: string }> {
  try {
    // 1. 先将文档状态标记为 indexing
    await updateKbDocumentStatus(env.DB, doc.id, 'indexing')

    // 2. 清理旧切片与对应向量
    const oldVectorIds = await deleteKbChunksByDocumentId(env.DB, doc.id)
    if (env.VECTORIZE_INDEX && oldVectorIds.length > 0) {
      try {
        await env.VECTORIZE_INDEX.deleteByIds(oldVectorIds)
      } catch (e) {
        console.warn('Failed to delete old vectors from Vectorize', e)
      }
    }

    // 3. 执行语义分块
    const rawChunks = splitTextIntoChunks(doc.content, 650, 80)
    if (rawChunks.length === 0) {
      await updateKbDocumentStatus(env.DB, doc.id, 'ready', 0)
      return { success: true, chunksCount: 0 }
    }

    // 4. 生成向量切片模型数据
    const kbChunks: KbChunk[] = rawChunks.map((chunkText, idx) => {
      const chunkId = `chunk_${doc.id}_${idx}_${Math.random().toString(36).substring(2, 6)}`
      return {
        id: chunkId,
        document_id: doc.id,
        domain: doc.domain,
        chunk_index: idx,
        content: chunkText,
        vector_id: `vec_${chunkId}`,
        created_at: Date.now()
      }
    })

    // 5. 调用 Workers AI 生成 Embedding 向量
    if (env.AI && env.VECTORIZE_INDEX) {
      const chunkTexts = kbChunks.map(c => c.content)
      // Workers AI 批量生成 embeddings
      const embedRes = await env.AI.run(EMBEDDING_MODEL, { text: chunkTexts })
      const vectorsData: number[][] = embedRes.data || embedRes

      if (vectorsData && Array.isArray(vectorsData)) {
        const vectorizeRecords = kbChunks.map((chunk, idx) => ({
          id: chunk.vector_id,
          values: vectorsData[idx],
          metadata: {
            document_id: doc.id,
            domain: doc.domain,
            rel_product_id: doc.rel_product_id || '',
            title: doc.title
          }
        }))

        // 写入 Vectorize
        await env.VECTORIZE_INDEX.upsert(vectorizeRecords)
      }
    } else {
      console.warn('Workers AI or Vectorize binding missing, skipped embedding upsert')
    }

    // 6. 保存切片元数据至 D1 并更新状态为 ready
    await saveKbChunks(env.DB, kbChunks)
    await updateKbDocumentStatus(env.DB, doc.id, 'ready', kbChunks.length)

    return { success: true, chunksCount: kbChunks.length }
  } catch (err: any) {
    console.error('Failed to index document', err)
    await updateKbDocumentStatus(env.DB, doc.id, 'error', undefined, err.message || 'Indexing failed')
    return { success: false, chunksCount: 0, error: err.message || 'Indexing failed' }
  }
}

/**
 * 知识库相似度检索接口 (Top-K Retrieval)
 * @param env 环境变量
 * @param query 查询关键词或用户问题
 * @param options 筛选与条数限制
 */
export async function searchKnowledge(
  env: Env,
  query: string,
  options?: {
    domains?: KbDomain[]
    relProductId?: string
    topK?: number
    minScore?: number
  }
): Promise<Array<{ chunk: KbChunk; score: number; title?: string }>> {
  const topK = options?.topK || 4
  const minScore = options?.minScore || 0.45

  if (!env.AI || !env.VECTORIZE_INDEX) {
    // 无向量环境降级：文本关键词检索 D1
    const docs = await getKbDocuments(env.DB, {
      domain: options?.domains?.[0],
      relProductId: options?.relProductId,
      search: query
    })
    return docs.slice(0, topK).map(d => ({
      chunk: {
        id: 'fallback_' + d.id,
        document_id: d.id,
        domain: d.domain,
        chunk_index: 0,
        content: d.content.substring(0, 400),
        vector_id: '',
        created_at: d.created_at
      },
      score: 0.8,
      title: d.title
    }))
  }

  // 1. 生成提问的 Query Embedding
  const embedRes = await env.AI.run(EMBEDDING_MODEL, { text: [query] })
  const queryVectors: number[][] = embedRes.data || embedRes
  const queryVector = queryVectors[0]

  // 2. 组装 Vectorize 元数据过滤条件
  const filter: any = {}
  if (options?.domains && options.domains.length === 1) {
    filter.domain = options.domains[0]
  } else if (options?.domains && options.domains.length > 1) {
    filter.domain = { $in: options.domains }
  }
  if (options?.relProductId) {
    filter.rel_product_id = options.relProductId
  }

  // 3. 执行向量余弦相似度查询
  const queryParams: any = { topK: topK * 2 }
  if (Object.keys(filter).length > 0) {
    queryParams.filter = filter
  }

  const vecResult = await env.VECTORIZE_INDEX.query(queryVector, queryParams)
  const matches = (vecResult.matches || []).filter((m: any) => m.score >= minScore).slice(0, topK)

  if (matches.length === 0) {
    return []
  }

  // 4. 根据 vector_id 批量反查 D1 得到原文内容
  const vectorIds = matches.map((m: any) => m.id)
  const chunks = await getKbChunksByVectorIds(env.DB, vectorIds)

  const chunkMap = new Map<string, KbChunk>()
  chunks.forEach(c => chunkMap.set(c.vector_id, c))

  return matches
    .map((m: any) => {
      const c = chunkMap.get(m.id)
      if (!c) return null
      return {
        chunk: c,
        score: m.score,
        title: m.metadata?.title
      }
    })
    .filter(Boolean) as Array<{ chunk: KbChunk; score: number; title?: string }>
}

/**
 * 单通道调用：Cloudflare Workers AI
 */
async function callCfWorkersAi(env: Env, channel: AiModelChannel, messages: any[]): Promise<string> {
  if (!env.AI) throw new Error('Workers AI 边缘模型绑定未开启')
  
  // 容错与自愈：若模型在废弃列表中或已被 Cloudflare 淘汰，平滑替换为 2026 最新官方稳定模型
  let modelName = (channel.model || '').trim()
  if (DEPRECATED_MODEL_MAP[modelName]) {
    modelName = DEPRECATED_MODEL_MAP[modelName]
  }
  if (!modelName) {
    modelName = '@cf/meta/llama-3.2-3b-instruct'
  }

  try {
    const res: any = await env.AI.run(modelName as any, {
      messages,
      max_tokens: channel.max_tokens || 1024,
      temperature: channel.temperature ?? 0.3
    })
    const text = res?.response ?? res?.text ?? res?.result?.response ?? (typeof res === 'string' ? res : '')
    if (!text) throw new Error('Workers AI 返回内容为空')
    return text
  } catch (err: any) {
    // 若特定模型报 5028 (deprecated) 或 5007 (not found)，终极降级到当前绝对可用的 llama-3.2-3b
    if (modelName !== '@cf/meta/llama-3.2-3b-instruct' && (String(err?.message || err).includes('deprecated') || String(err?.message || err).includes('No such model'))) {
      const retryRes: any = await env.AI.run('@cf/meta/llama-3.2-3b-instruct' as any, {
        messages,
        max_tokens: channel.max_tokens || 1024,
        temperature: 0.3
      })
      const retryText = retryRes?.response ?? retryRes?.text ?? retryRes?.result?.response ?? (typeof retryRes === 'string' ? retryRes : '')
      if (retryText) return retryText
    }
    throw err
  }
}

/**
 * 单通道调用：OpenAI 兼容协议 (DeepSeek, OpenAI, Kimi, Ollama, 通义千问等)
 */
async function callOpenAiCompatible(channel: AiModelChannel, messages: any[]): Promise<string> {
  let endpoint = (channel.endpoint || 'https://api.openai.com/v1').trim().replace(/\/+$/, '')
  if (!endpoint.endsWith('/chat/completions')) {
    endpoint += '/chat/completions'
  }
  const headers: Record<string, string> = {
    'Content-Type': 'application/json'
  }
  if (channel.api_key?.trim()) {
    headers['Authorization'] = `Bearer ${channel.api_key.trim()}`
  }

  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(), 12000) // 12 秒超时

  try {
    const res = await fetch(endpoint, {
      method: 'POST',
      headers,
      body: JSON.stringify({
        model: channel.model,
        messages,
        temperature: channel.temperature ?? 0.3,
        max_tokens: channel.max_tokens || 1000
      }),
      signal: controller.signal
    })
    if (!res.ok) {
      const errText = await res.text().catch(() => '')
      throw new Error(`HTTP ${res.status}: ${errText.substring(0, 150)}`)
    }
    const data: any = await res.json()
    const content = data?.choices?.[0]?.message?.content || ''
    if (!content) throw new Error('模型返回空内容')
    return content
  } finally {
    clearTimeout(timer)
  }
}

/**
 * 连通性测试函数 (供后台管理端一键测试通道有效性与耗时)
 */
export async function testAiChannel(env: Env, channel: AiModelChannel): Promise<{ success: boolean; latencyMs: number; error?: string; reply?: string }> {
  const start = Date.now()
  const testMessages = [
    { role: 'system', content: 'You are a test assistant. Reply with "pong" only.' },
    { role: 'user', content: 'ping' }
  ]
  try {
    let reply = ''
    if (channel.type === 'cf_workers_ai') {
      reply = await callCfWorkersAi(env, channel, testMessages)
    } else {
      reply = await callOpenAiCompatible(channel, testMessages)
    }
    const latencyMs = Date.now() - start
    return { success: true, latencyMs, reply: reply.trim().substring(0, 50) }
  } catch (e: any) {
    const latencyMs = Date.now() - start
    return { success: false, latencyMs, error: e.message || '连接失败' }
  }
}

/**
 * 多通道轮换与故障自动降级执行器 (Failover Execution Pool)
 * 遍历已启用的通道，遇报错自动无感尝试下一通道，保证前端访客无异常感知
 */
async function callLlmWithFallback(
  env: Env,
  messages: any[],
  configuredChannels?: AiModelChannel[]
): Promise<{ text: string; channelName: string }> {
  const pool = (configuredChannels && configuredChannels.length > 0)
    ? configuredChannels.filter(c => c.enabled)
    : DEFAULT_MODEL_POOL.filter(c => c.enabled)

  const activeChannels = pool.length > 0 ? pool : DEFAULT_MODEL_POOL
  const errors: string[] = []

  for (const ch of activeChannels) {
    try {
      let output = ''
      if (ch.type === 'cf_workers_ai') {
        output = await callCfWorkersAi(env, ch, messages)
      } else {
        output = await callOpenAiCompatible(ch, messages)
      }
      if (output.trim()) {
        return { text: output.trim(), channelName: ch.name }
      }
    } catch (err: any) {
      console.warn(`[AI Failover] 通道【${ch.name}】调用失败: ${err.message}，正在无感尝试下一通道...`)
      errors.push(`${ch.name}: ${err.message}`)
    }
  }

  throw new Error(`全部 ${activeChannels.length} 个 AI 模型通道均调用失败: ` + errors.join('; '))
}

/**
 * 智能客服问答 RAG 逻辑 (支持动态读取后台模型池配置与自定义人设)
 * @param env 环境变量
 * @param question 访客问题
 * @param conversationHistory 历史上下文 (可选)
 */
export async function askKnowledge(
  env: Env,
  question: string,
  conversationHistory: Array<{ role: 'user' | 'assistant'; content: string }> = []
): Promise<{ answer: string; sources: Array<{ title?: string; score: number }>; used_channel?: string }> {
  // 客服问答优先检索 support 与 product 知识
  const searchResults = await searchKnowledge(env, question, {
    domains: ['support', 'product'],
    topK: 3,
    minScore: 0.5
  })

  const contextText = searchResults.map((r, i) => `[参考资料 ${i + 1} - ${r.title || '企业资料'}]:\n${r.chunk.content}`).join('\n\n')

  // 动态读取后台配置的客服人设 System Prompt
  const customPrompt = await getSystemSetting(env.DB, 'ai_system_prompt')
  const defaultPrompt = `你是一位专业、礼貌、严谨的企业官方智能客服顾问。
你的任务是根据提供的官方企业知识库参考资料，精准解答客户提出的问题。

回答规则：
1. 优先根据给出的参考资料真实作答，保持语气亲切、客观、有帮助。
2. 如果参考资料中没有提到相关信息，请诚实回答“关于该问题目前暂未查询到确切信息，我已为您记录，稍后可转接人工客服为您进一步确认”，切勿胡乱编造任何事实或政策。
3. 排版条理清晰，多使用分点说明。`

  const basePrompt = (customPrompt && customPrompt.trim()) ? customPrompt.trim() : defaultPrompt
  const systemPrompt = `${basePrompt}

官方参考资料：
${contextText || '（暂无直接相关的参考资料）'}`

  // 动态读取后台配置的 AI 模型轮换池
  let modelPool: AiModelChannel[] = DEFAULT_MODEL_POOL
  try {
    const poolJson = await getSystemSetting(env.DB, 'ai_model_pool')
    if (poolJson) {
      const parsed = JSON.parse(poolJson)
      if (Array.isArray(parsed) && parsed.length > 0) {
        modelPool = parsed
      }
    }
  } catch (e) {}

  const messages = [
    { role: 'system', content: systemPrompt },
    ...conversationHistory.slice(-4),
    { role: 'user', content: question }
  ]

  try {
    const { text, channelName } = await callLlmWithFallback(env, messages, modelPool)
    return {
      answer: text,
      sources: searchResults.map(r => ({ title: r.title, score: r.score })),
      used_channel: channelName
    }
  } catch (err: any) {
    console.error('All AI channels failed in askKnowledge:', err)
    // 降级兜底方案：直接返回知识库最匹配的切片原文摘要
    const fallbackAnswer = searchResults.length > 0
      ? `根据企业知识库为您查询到以下参考信息：\n${searchResults[0].chunk.content}`
      : '您好！人工客服当前忙，稍后将为您回复，请随时留言。'
    return {
      answer: fallbackAnswer,
      sources: searchResults.map(r => ({ title: r.title, score: r.score })),
      used_channel: '本地知识库降级兜底'
    }
  }
}

export interface AiTranslateParams {
  sourceLang: string
  targetLangs: string[]
  fields: Record<string, string>
}

/**
 * 通用多语言 AI 智能翻译服务
 * 基于智能模型轮换池 (Failover Pool) 批量翻译多语言字段，保留 HTML 结构
 */
export async function translateContentWithAi(
  env: Env,
  params: AiTranslateParams
): Promise<{ translations: Record<string, Record<string, string>>; used_channel: string }> {
  const { sourceLang, targetLangs, fields } = params
  if (!targetLangs || targetLangs.length === 0 || !fields || Object.keys(fields).length === 0) {
    return { translations: {}, used_channel: 'none' }
  }

  let modelPool: AiModelChannel[] = DEFAULT_MODEL_POOL
  try {
    const poolJson = await getSystemSetting(env.DB, 'ai_model_pool')
    if (poolJson) {
      const parsed = JSON.parse(poolJson)
      if (Array.isArray(parsed) && parsed.length > 0) modelPool = parsed
    }
  } catch (e) {}

  const translations: Record<string, Record<string, string>> = {}
  let lastUsedChannel = 'unknown'

  for (const targetLang of targetLangs) {
    if (targetLang === sourceLang) continue

    const prompt = `你是一个多语言本地化翻译引擎。
请将以下 JSON 中的每个字段从源语言【${sourceLang}】翻译为目标语言【${targetLang}】。
规则要求：
1. 保持原文商业、营销与产品说明的专业语气，译文自然准确；
2. 若文本包含 HTML 标签（如 <p>, <h1>, <ul>, <li>, <img>, <a> 等），必须严密保留所有 HTML 标签及其属性，仅翻译标签之间的可读文字；
3. 输出必须是合法纯净的 JSON 格式，Key 与输入完全一致，不要包含任何 markdown 解释或额外包裹。

待翻译 JSON 数据：
${JSON.stringify(fields, null, 2)}`

    const messages = [
      { role: 'system', content: 'You are a professional localization translation engine. You only reply with raw JSON.' },
      { role: 'user', content: prompt }
    ]

    try {
      const { text, channelName } = await callLlmWithFallback(env, messages, modelPool)
      lastUsedChannel = channelName

      const cleaned = text.replace(/```(?:json)?/gi, '').replace(/```/g, '').trim()
      const jsonStart = cleaned.indexOf('{')
      const jsonEnd = cleaned.lastIndexOf('}')
      if (jsonStart !== -1 && jsonEnd !== -1) {
        const parsed = JSON.parse(cleaned.substring(jsonStart, jsonEnd + 1))
        translations[targetLang] = parsed
      } else {
        translations[targetLang] = fields
      }
    } catch (err) {
      console.error(`AI translation failed for ${targetLang}:`, err)
      translations[targetLang] = fields
    }
  }

  return { translations, used_channel: lastUsedChannel }
}
