import { Hono } from 'hono'
import type { Env } from '../types'
import {
  getAllCustomForms,
  getCustomFormByKey,
  createCustomForm,
  updateCustomForm,
  deleteCustomForm,
  getFormSubmissions,
  insertFormSubmission,
  deleteFormSubmission
} from '../db/forms'

export const formsRouter = new Hono<{ Bindings: Env }>()

// 域名白名单安全校验辅助函数
function isDomainAllowed(allowedDomains: string | undefined, req: any): boolean {
  if (!allowedDomains || !allowedDomains.trim()) return true

  const origin = req.header('origin') || req.header('referer') || ''
  if (!origin) return true

  try {
    const host = new URL(origin).hostname.toLowerCase()
    if (host === 'localhost' || host === '127.0.0.1') return true

    const list = allowedDomains
      .split(/[\n,]+/)
      .map(d => d.trim().toLowerCase())
      .filter(Boolean)

    return list.some(d => host === d || host.endsWith('.' + d))
  } catch (e) {
    return false
  }
}

// ==================== 1. 后台管理接口 (Admin) ====================

formsRouter.get('/admin/forms', async (c) => {
  try {
    const list = await getAllCustomForms(c.env.DB)
    return c.json({ success: true, data: list })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

formsRouter.post('/admin/forms', async (c) => {
  try {
    const body = await c.req.json()
    const { key, title, description, allowed_domains, fields, style } = body

    if (!key || !title) {
      return c.json({ success: false, message: '表单名称与调用 Key 为必填项' }, 400)
    }

    const cleanedKey = key.trim().toLowerCase().replace(/[^a-z0-9_]/g, '_')
    const existing = await getCustomFormByKey(c.env.DB, cleanedKey)
    if (existing) {
      return c.json({ success: false, message: `调用 Key [${cleanedKey}] 已存在，请更换` }, 400)
    }

    const created = await createCustomForm(c.env.DB, {
      key: cleanedKey,
      title: title.trim(),
      description,
      allowed_domains,
      fields: fields || [],
      style: style || {}
    })

    return c.json({ success: true, data: created })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

formsRouter.put('/admin/forms/:id', async (c) => {
  try {
    const id = c.req.param('id')
    const body = await c.req.json()
    const { title, description, allowed_domains, fields, style } = body

    if (!title) {
      return c.json({ success: false, message: '表单名称不能为空' }, 400)
    }

    await updateCustomForm(c.env.DB, id, {
      title: title.trim(),
      description,
      allowed_domains,
      fields: fields || [],
      style: style || {}
    })

    return c.json({ success: true })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

formsRouter.delete('/admin/forms/:id', async (c) => {
  try {
    const id = c.req.param('id')
    await deleteCustomForm(c.env.DB, id)
    return c.json({ success: true })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

formsRouter.get('/admin/forms/:key/submissions', async (c) => {
  try {
    const key = c.req.param('key')
    const list = await getFormSubmissions(c.env.DB, key)
    return c.json({ success: true, data: list })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

formsRouter.delete('/admin/forms/submissions/:id', async (c) => {
  try {
    const id = c.req.param('id')
    await deleteFormSubmission(c.env.DB, id)
    return c.json({ success: true })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

// ==================== 2. 前端嵌入式公开接口 (Public) ====================

/**
 * 前端嵌入组件获取表单配置信息 (GET)
 */
formsRouter.get('/public/forms/:key', async (c) => {
  try {
    const key = c.req.param('key')
    const form = await getCustomFormByKey(c.env.DB, key)

    if (!form || form.status === 'disabled') {
      return c.json({ success: false, message: '该表单不存在或已停用' }, 404)
    }

    // 域名防盗链安全校验
    if (!isDomainAllowed(form.allowed_domains, c.req)) {
      return c.json({
        success: false,
        message: '当前域名未获得该在线表单的调用授权，请联系管理员配置安全域名白名单'
      }, 403)
    }

    return c.json({
      success: true,
      data: {
        key: form.key,
        title: form.title,
        description: form.description,
        fields: form.fields,
        style: form.style
      }
    })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

/**
 * 前端嵌入组件提交表单数据 (POST)
 */
formsRouter.post('/public/forms/:key/submit', async (c) => {
  try {
    const key = c.req.param('key')
    const form = await getCustomFormByKey(c.env.DB, key)

    if (!form || form.status === 'disabled') {
      return c.json({ success: false, message: '该表单不存在或已停用' }, 404)
    }

    // 域名安全校验
    if (!isDomainAllowed(form.allowed_domains, c.req)) {
      return c.json({ success: false, message: '当前域名未在授权白名单中，禁止提交' }, 403)
    }

    const body = await c.req.json()
    const { visitor_id, data, source_url } = body

    if (!data || typeof data !== 'object') {
      return c.json({ success: false, message: '提交数据格式错误' }, 400)
    }

    // 必填字段校验
    for (const field of form.fields) {
      if (field.required) {
        const val = data[field.key]
        if (val === undefined || val === null || val === '' || (Array.isArray(val) && val.length === 0)) {
          return c.json({ success: false, message: `请填写【${field.label}】` }, 400)
        }
      }
    }

    // 获取客户端 IP 与地理位置
    const ip = c.req.header('cf-connecting-ip') || c.req.header('x-real-ip') || ''
    const country = (c.req.raw as any)?.cf?.country || ''
    const city = (c.req.raw as any)?.cf?.city || ''

    const subId = await insertFormSubmission(c.env.DB, {
      form_key: key,
      visitor_id,
      data,
      ip,
      country,
      city,
      source_url: source_url || c.req.header('referer') || ''
    })

    return c.json({
      success: true,
      data: {
        id: subId,
        message: form.style?.success_message || '提交成功！'
      }
    })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})
